// Funciones de logística INVENTADAS para practicar (no son de ninguna empresa real).

const DIVISOR_VOLUMETRICO = 5000; // regla inventada: 5000 cm³ equivalen a 1 kg

export function pesoCobrable(pesoKg, largoCm, anchoCm, altoCm) {
  if (![pesoKg, largoCm, anchoCm, altoCm].every((n) => Number.isFinite(n) && n > 0)) {
    throw new RangeError('peso y medidas deben ser números positivos');
  }
  const volumetrico = (largoCm * anchoCm * altoCm) / DIVISOR_VOLUMETRICO;
  const mayor = Math.max(pesoKg, volumetrico);
  return Math.ceil(mayor * 2) / 2; // se cobra por medio kilo, siempre hacia arriba
}

export function paletsNecesarios(cajas, cajasPorPalet) {
  if (!Number.isInteger(cajas) || cajas < 0) throw new RangeError('cajas inválidas');
  if (!Number.isInteger(cajasPorPalet) || cajasPorPalet <= 0) throw new RangeError('cajasPorPalet inválido');
  return Math.ceil(cajas / cajasPorPalet);
}

const TARIFAS = {
  CABA: { base: 2500, porKg: 400 },
  GBA: { base: 3500, porKg: 550 },
  INTERIOR: { base: 6000, porKg: 900 },
};

export function calcularFlete(zona, kgCobrables) {
  const t = TARIFAS[zona];
  if (!t) throw new Error('zona desconocida: ' + zona);
  return t.base + t.porKg * kgCobrables;
}

// fecha 'AAAA-MM-DD' (UTC). Suma días hábiles saltando sábados, domingos y feriados.
export function fechaPrometida(desde, diasHabiles, feriados = []) {
  const f = new Date(desde + 'T00:00:00Z');
  let faltan = diasHabiles;
  while (faltan > 0) {
    f.setUTCDate(f.getUTCDate() + 1);
    const dia = f.getUTCDay(); // 0 domingo, 6 sábado
    const iso = f.toISOString().slice(0, 10);
    if (dia !== 0 && dia !== 6 && !feriados.includes(iso)) faltan--;
  }
  return f.toISOString().slice(0, 10);
}

