import { pesoCobrable, calcularFlete } from './flete.mjs';

// Las dependencias que tocan el mundo (guardar, avisar, el reloj) llegan por parámetro.
export function confirmarEnvio(envio, { guardar, avisar, ahora }) {
  const kg = pesoCobrable(envio.pesoKg, ...envio.medidas);
  const costo = calcularFlete(envio.zona, kg);
  const registro = { id: envio.id, zona: envio.zona, kg, costo, confirmadoEn: ahora().toISOString() };
  guardar(registro);
  avisar({ telefono: envio.telefono, texto: `Tu envío ${envio.id} cuesta $${costo}` });
  return registro;
}

