// El depósito de práctica abre de lunes a viernes, de 8 a 18, hora de Buenos Aires (UTC-3 todo el año).
const A_HORA_BA = (fecha) => new Date(fecha.getTime() - 3 * 3600 * 1000); // corre el reloj a UTC-3 y lee con getUTC*

// Versión 1: lee el reloj del sistema por dentro. Imposible de probar con valores fijos.
export function abiertoAhora() {
  return abiertoEn(new Date());
}

// Versión 2: función pura. Recibe el momento que se quiere evaluar.
export function abiertoEn(fecha) {
  const ba = A_HORA_BA(fecha);
  const dia = ba.getUTCDay();
  const hora = ba.getUTCHours();
  return dia >= 1 && dia <= 5 && hora >= 8 && hora < 18;
}

// Elegir andén al azar: el generador de azar llega por parámetro (por defecto, el real).
export function elegirAnden(andenes, azar = Math.random) {
  return andenes[Math.floor(azar() * andenes.length)];
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { abiertoAhora, abiertoEn, elegirAnden } from './deposito.mjs';

// MALA: depende de cuándo se corra. Pasa de martes a las 10 y falla el sábado.
test('MALA: el depósito está abierto ahora', () => {
  assert.equal(abiertoAhora(), true);
});

// BUENAS: el momento es un dato de la prueba.
test('abiertoEn: martes 10:00 hora de Buenos Aires está abierto', () => {
  assert.equal(abiertoEn(new Date('2026-11-17T13:00:00Z')), true);   // 13:00 UTC = 10:00 en BA
});
test('abiertoEn: sábado a la mañana está cerrado', () => {
  assert.equal(abiertoEn(new Date('2026-11-14T13:00:00Z')), false);
});
test('abiertoEn: a las 18:00 en punto ya cerró (el borde)', () => {
  assert.equal(abiertoEn(new Date('2026-11-17T21:00:00Z')), false);
  assert.equal(abiertoEn(new Date('2026-11-17T20:59:00Z')), true);
});

// El azar controlado: con un generador falso, el resultado es siempre el mismo.
test('elegirAnden: con azar 0,99 elige el último andén', () => {
  assert.equal(elegirAnden(['A', 'B', 'C', 'D'], () => 0.99), 'D');
});

// La alternativa: congelar el reloj del sistema.
test('MALA pero arreglada con reloj simulado', (t) => {
  t.mock.timers.enable({ apis: ['Date'], now: Date.parse('2026-11-17T13:00:00Z') });
  assert.equal(abiertoAhora(), true);
});

